CREATE FORCE VIEW "PUBLIC"."SALE_LISTING"("SCHOOL_ID", "SELNO", "SELLER", "SELLER_MEMBER_ID", "CATEGORY", "NAME", "OPRICE", "BUYPRICE", "WISHPRICE", "DETAIL", "DISCOUNT", "STARTTIME", "ENDTIME", "REGTIME", "STATUS", "PHOTO1", "PHOTO2", "PHOTO3", "LOCATION", "ICON", "BUMPED_AT", "SELLER_TEMPERATURE", "CURRENT_PRICE", "EXPOSURE_PRIORITY") AS
SELECT
    "S"."SCHOOL_ID",
    "S"."SELNO",
    "S"."SELLER",
    "S"."SELLER_MEMBER_ID",
    "S"."CATEGORY",
    "S"."NAME",
    "S"."OPRICE",
    "S"."BUYPRICE",
    "S"."WISHPRICE",
    "S"."DETAIL",
    "S"."DISCOUNT",
    "S"."STARTTIME",
    "S"."ENDTIME",
    "S"."REGTIME",
    "S"."STATUS",
    "S"."PHOTO1",
    "S"."PHOTO2",
    "S"."PHOTO3",
    "S"."LOCATION",
    "S"."ICON",
    "S"."BUMPED_AT",
    COALESCE(CAST("ST"."TEMP" AS DECIMAL(5, 1)) / 10, "S"."SELLER_TEMPERATURE") AS "SELLER_TEMPERATURE",
    CAST(CASE WHEN ("STATUS" = U&'\d310\b9e4\c911')
        AND ("DISCOUNT" > 0)
        AND ("STARTTIME" <= CURRENT_TIMESTAMP)
        AND ("ENDTIME" > CURRENT_TIMESTAMP) THEN FLOOR((CAST("OPRICE" AS DECIMAL(18, 2)) * (100 - "DISCOUNT")) / 100) ELSE "OPRICE" END AS INTEGER) AS "CURRENT_PRICE",
    CASE WHEN "STATUS" = U&'\ac70\b798\c644\b8cc' THEN 4 WHEN "STATUS" = U&'\c608\c57d\c911' THEN 3 WHEN "REGTIME" > DATEADD(HOUR, -24, CURRENT_TIMESTAMP) THEN 0 WHEN ("BUMPED_AT" IS NOT NULL)
        AND ("BUMPED_AT" > DATEADD(HOUR, -24, CURRENT_TIMESTAMP)) THEN 1 ELSE 2 END AS "EXPOSURE_PRIORITY"
FROM "PUBLIC"."SALES" "S"
LEFT OUTER JOIN "PUBLIC"."STUDENT" "ST"
    ON ("ST"."UNISNO" = "S"."SELLER")
    AND (("S"."SELLER_MEMBER_ID" IS NULL)
    OR ("ST"."MEMBER_ID" = "S"."SELLER_MEMBER_ID"));       
CREATE FORCE VIEW "PUBLIC"."PRODUCTS"("ID", "TITLE", "PRICE", "CATEGORY", "LOCATION", "ICON") AS
SELECT
    "SELNO" AS "ID",
    "NAME" AS "TITLE",
    "CURRENT_PRICE" AS "PRICE",
    "CATEGORY",
    "LOCATION",
    "ICON"
FROM "PUBLIC"."SALE_LISTING";          
