CREATE FORCE VIEW "PUBLIC"."ENGAGEMENT_TARGETS"("TARGET_TYPE", "TARGET_ID", "TITLE", "SUBTITLE", "PRICE", "PHOTO", "PARENT_ID", "SCHOOL_ID") AS
(((SELECT
    'SALE' AS "TARGET_TYPE",
    "SELNO" AS "TARGET_ID",
    "NAME" AS "TITLE",
    "LOCATION" AS "SUBTITLE",
    "CURRENT_PRICE" AS "PRICE",
    "PHOTO1" AS "PHOTO",
    "SELNO" AS "PARENT_ID",
    "SCHOOL_ID"
FROM "PUBLIC"."SALE_LISTING")
UNION ALL
(SELECT
    'POST',
    "POST_ID",
    "TITLE",
    SUBSTRING("CONTENT" FROM 1 FOR 160),
    NULL,
    NULL,
    "POST_ID",
    "SCHOOL_ID"
FROM "PUBLIC"."BOARD_POSTS"))
UNION ALL
(SELECT
    'SHOP',
    "SHOPID",
    "SHOPNAME",
    "ADDRESS",
    NULL,
    "PHOTO",
    "SHOPID",
    "SCHOOL_ID"
FROM "PUBLIC"."SHOPS"
WHERE "CHECKED" = TRUE))
UNION ALL
(SELECT
    'COMMENT',
    "COMMENT_ID",
    SUBSTRING("C"."CONTENT" FROM 1 FOR 100),
    "P"."TITLE",
    NULL,
    NULL,
    "C"."POST_ID",
    "P"."SCHOOL_ID"
FROM "PUBLIC"."BOARD_COMMENTS" "C"
INNER JOIN "PUBLIC"."BOARD_POSTS" "P"
    ON 1=1
WHERE "P"."POST_ID" = "C"."POST_ID");            
