CREATE MEMORY TABLE "PUBLIC"."SCHOOL"(
    "LATITUDE" NUMERIC(10, 7),
    "LONGITUDE" NUMERIC(10, 7),
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 10) DEFAULT ON NULL NOT NULL,
    "VERSION" BIGINT,
    "CAMPUS_CODE" CHARACTER VARYING(20),
    "NAME" CHARACTER VARYING(50) NOT NULL,
    "REGION" CHARACTER VARYING(50) NOT NULL,
    "EMAIL_DOMAIN" CHARACTER VARYING(100) NOT NULL,
    "MAP_IMAGE" CHARACTER VARYING(100),
    "PHOTO" CHARACTER VARYING(100),
    "ADDRESS" CHARACTER VARYING(200)
);     
