ALTER TABLE "PUBLIC"."SHOPS" ADD CONSTRAINT "PUBLIC"."CK_SHOP_COORDINATES" CHECK((("LATITUDE" IS NULL)
    AND ("LONGITUDE" IS NULL))
    OR (("LATITUDE" IS NOT NULL)
    AND ("LONGITUDE" IS NOT NULL)
    AND ("LATITUDE" BETWEEN -90 AND 90)
    AND ("LONGITUDE" BETWEEN -180 AND 180))) NOCHECK;   
ALTER TABLE "PUBLIC"."SALES" ADD CONSTRAINT "PUBLIC"."CK_SALE_PRICE" CHECK(("OPRICE" >= 0)
    AND (("BUYPRICE" IS NULL)
    OR ("BUYPRICE" >= 0))
    AND (("WISHPRICE" IS NULL)
    OR ("WISHPRICE" >= 0))) NOCHECK;    
ALTER TABLE "PUBLIC"."SALES" ADD CONSTRAINT "PUBLIC"."CK_SALE_DISCOUNT_TIME" CHECK((("DISCOUNT" = 0)
    AND ("STARTTIME" IS NULL)
    AND ("ENDTIME" IS NULL))
    OR (("DISCOUNT" BETWEEN 1 AND 99)
    AND ("STARTTIME" IS NOT NULL)
    AND ("ENDTIME" IS NOT NULL)
    AND ("ENDTIME" = DATEADD(HOUR, 24, "STARTTIME")))) NOCHECK; 
ALTER TABLE "PUBLIC"."STUDENT" ADD CONSTRAINT "PUBLIC"."CK_STUDENT_TEMP" CHECK("TEMP" BETWEEN 0 AND 990) NOCHECK;             
ALTER TABLE "PUBLIC"."TRADE_ORDERS" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_CC" CHECK("AGREED_PRICE" >= 0) NOCHECK;               
ALTER TABLE "PUBLIC"."SALES" ADD CONSTRAINT "PUBLIC"."CK_SALE_DISCOUNT_AMOUNT" CHECK(("DISCOUNT" = 0)
    OR (FLOOR((CAST("OPRICE" AS DECIMAL(18, 2)) * (100 - "DISCOUNT")) / 100) >= 1)) NOCHECK;           
ALTER TABLE "PUBLIC"."CONTENT_REACTIONS" ADD CONSTRAINT "PUBLIC"."CK_REACTION_KIND" CHECK("KIND" IN('LIKE', 'BOOKMARK')) NOCHECK;             
ALTER TABLE "PUBLIC"."NOTIFICATION_DELIVERIES" ADD CONSTRAINT "PUBLIC"."CK_NOTIFICATION_CHANNEL" CHECK("CHANNEL" IN('SMS', 'EMAIL', 'KAKAO')) NOCHECK;        
ALTER TABLE "PUBLIC"."MANNER_RATINGS" ADD CONSTRAINT "PUBLIC"."CK_RATING_SELF" CHECK("REVIEWER_UNISNO" <> "RECIPIENT_UNISNO") NOCHECK;        
ALTER TABLE "PUBLIC"."TRADE_ORDERS" ADD CONSTRAINT "PUBLIC"."CK_ORDER_COORDINATES" CHECK((("LATITUDE" IS NULL)
    AND ("LONGITUDE" IS NULL))
    OR (("LATITUDE" IS NOT NULL)
    AND ("LONGITUDE" IS NOT NULL)
    AND ("LATITUDE" BETWEEN -90 AND 90)
    AND ("LONGITUDE" BETWEEN -180 AND 180))) NOCHECK;           
ALTER TABLE "PUBLIC"."CONTENT_REACTIONS" ADD CONSTRAINT "PUBLIC"."CK_REACTION_TYPE" CHECK("TARGET_TYPE" IN('SALE', 'POST', 'SHOP', 'COMMENT')) NOCHECK;       
ALTER TABLE "PUBLIC"."TRADE_ORDERS" ADD CONSTRAINT "PUBLIC"."CK_ORDER_STATUS" CHECK("STATUS" IN('RESERVED', 'PAYMENT_READY', 'WAITING_FOR_DEPOSIT', 'PAID', 'COMPLETED', U&'\ac70\b798\c644\b8cc', 'CANCELED')) NOCHECK;      
ALTER TABLE "PUBLIC"."SALES" ADD CONSTRAINT "PUBLIC"."CK_SALE_STATUS" CHECK("STATUS" IN(U&'\d310\b9e4\c911', U&'\c608\c57d\c911', U&'\ac70\b798\c644\b8cc')) NOCHECK;         
ALTER TABLE "PUBLIC"."MANNER_RATINGS" ADD CONSTRAINT "PUBLIC"."CK_RATING_FEEDBACK" CHECK("FEEDBACK" IN('GOOD', 'BAD')) NOCHECK;               
ALTER TABLE "PUBLIC"."SHOPS" ADD CONSTRAINT "PUBLIC"."CK_SHOP_STATUS" CHECK("STATUS" IN(U&'\c601\c5c5\c911', U&'\d63c\c7a1', U&'\c601\c5c5\c885\b8cc', U&'\d734\bb34')) NOCHECK;              
ALTER TABLE "PUBLIC"."SALES" ADD CONSTRAINT "PUBLIC"."CK_SALE_DISCOUNT" CHECK("DISCOUNT" BETWEEN 0 AND 99) NOCHECK;           
ALTER TABLE "PUBLIC"."MEMBER" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_87" UNIQUE NULLS DISTINCT ("BUSINESS_NO");  
ALTER TABLE "PUBLIC"."SCHOOL" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_91" UNIQUE NULLS DISTINCT ("CAMPUS_CODE");  
ALTER TABLE "PUBLIC"."SHOPS" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_4B" UNIQUE NULLS DISTINCT ("OWNER_MEMBER_ID");               
ALTER TABLE "PUBLIC"."BUSINESS_CATEGORIES" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_83" UNIQUE NULLS DISTINCT ("NAME");            
ALTER TABLE "PUBLIC"."MANNER_RATINGS" ADD CONSTRAINT "PUBLIC"."UQ_RATING_ORDER_REVIEWER" UNIQUE NULLS DISTINCT ("ORDER_ID", "REVIEWER_UNISNO");               
ALTER TABLE "PUBLIC"."NOTIFICATION_DELIVERIES" ADD CONSTRAINT "PUBLIC"."UQ_NOTIFICATION_CHANNEL" UNIQUE NULLS DISTINCT ("NOTIFICATION_ID", "CHANNEL");        
ALTER TABLE "PUBLIC"."SCHOOL" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_917" UNIQUE NULLS DISTINCT ("NAME");        
ALTER TABLE "PUBLIC"."STUDENT" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_BA" UNIQUE NULLS DISTINCT ("MEMBER_ID");   
ALTER TABLE "PUBLIC"."MEMBER" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_875" UNIQUE NULLS DISTINCT ("ACCOUNT_KEY"); 
ALTER TABLE "PUBLIC"."SELLER_NOTIFICATIONS" ADD CONSTRAINT "PUBLIC"."UQ_NOTIFICATION_ORDER_RECIPIENT" UNIQUE NULLS DISTINCT ("ORDER_ID", "SELLER_MEMBER_ID"); 
ALTER TABLE "PUBLIC"."MEMBER" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_8755" UNIQUE NULLS DISTINCT ("EMAIL");      
ALTER TABLE "PUBLIC"."TRADE_REVIEWS" ADD CONSTRAINT "PUBLIC"."UK_TRADE_REVIEW" UNIQUE NULLS DISTINCT ("ORDER_ID", "REVIEWER_ID");             
ALTER TABLE "PUBLIC"."BOARD_CATEGORIES" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_57" UNIQUE NULLS DISTINCT ("CATEGORY_NAME");      
ALTER TABLE "PUBLIC"."TRADE_ORDERS" ADD CONSTRAINT "PUBLIC"."FK_ORDER_SALE" FOREIGN KEY("SELNO") REFERENCES "PUBLIC"."SALES"("SELNO") NOCHECK;
ALTER TABLE "PUBLIC"."ADMIN_ACTION_LOGS" ADD CONSTRAINT "PUBLIC"."FK_ADMIN_ACTION_SHOP" FOREIGN KEY("SHOP_ID") REFERENCES "PUBLIC"."SHOPS"("SHOPID") NOCHECK; 
ALTER TABLE "PUBLIC"."SALES" ADD CONSTRAINT "PUBLIC"."FK_SALE_SELLER_MEMBER" FOREIGN KEY("SELLER_MEMBER_ID") REFERENCES "PUBLIC"."STUDENT"("MEMBER_ID") NOCHECK;              
ALTER TABLE "PUBLIC"."SELLER_NOTIFICATIONS" ADD CONSTRAINT "PUBLIC"."FK_NOTIFICATION_ORDER" FOREIGN KEY("ORDER_ID") REFERENCES "PUBLIC"."TRADE_ORDERS"("ORDER_ID") NOCHECK;   
ALTER TABLE "PUBLIC"."MANNER_RATINGS" ADD CONSTRAINT "PUBLIC"."FK_RATING_RECIPIENT" FOREIGN KEY("RECIPIENT_UNISNO") REFERENCES "PUBLIC"."STUDENT"("UNISNO") NOCHECK;          
